// [MEDIUM_PRIORITY] UX_POLISH: Error state handled
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audioimport android.media.AudioFormat as AndroidAudioFormatimport android.media.AudioRecordimport android.media.MediaRecorderimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.Jobimport kotlinx.coroutines.cancelimport kotlinx.coroutines.channels.Channelimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.receiveAsFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launchimport kotlin.coroutines.CoroutineContext/** * NOUS — Audio source abstraction. * * Wraps Android's [AudioRecord] for testability. Production code uses * [DefaultAudioSource] (which wraps a real AudioRecord); tests use * [FakeAudioSource] (which emits pre-defined chunks). * * ## Permission * * Implementations MUST check `RECORD_AUDIO` permission before starting. * [DefaultAudioSource.start] returns false if permission is missing or if * the microphone is already in use by another app with higher priority. * * ## Foreground Service Requirement * * Android 9+ requires a foreground service of type `microphone` for background * audio capture. The audio source itself doesn't enforce this — the caller * (VoiceService) is responsible. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */interface AudioSource {    /** Sentinel value indicating no audio session ID is available. */    companion object {        const val NO_SESSION: Int = -1    }    /**     * Start capturing audio.     *     * @return true if capture started successfully, false if mic unavailable     *         (permission denied, busy, or hardware error)     */    suspend fun start(): Boolean    /**     * Stop capturing audio. Releases the microphone (other apps can use it).     *     * Safe to call multiple times.     */    fun stop()    /**     * The audio session ID (for attaching hardware audio effects).     *     * Returns [NO_SESSION] if not started or unavailable.     */    val audioSessionId: Int    /**     * Stream of raw audio chunks from the microphone.     *     * Each chunk is [AudioFormat.FRAME_DURATION_MS] ms (20 ms = 320 samples     * at 16 kHz). The flow completes when [stop] is called.     */    fun chunkStream(): Flow<AudioChunk>    /** Release native resources. After release, the source is unusable. */    fun release()}/** * Default audio source backed by Android's [AudioRecord]. * * Configured for: *   - 16 kHz sample rate (speech quality) *   - 16-bit PCM (96 dB dynamic range) *   - Mono (single channel) *   - AudioSource.VOICE_RECOGNITION (no phone-call preprocessing) * * ## Buffer Sizing * * AudioRecord buffer is sized for low latency: 4 × frame size = 80 ms buffer. * This is small enough for real-time processing but large enough to avoid * underruns on most devices. * * ## Reading Loop * * A coroutine on a dedicated dispatcher reads from AudioRecord in 20 ms chunks * and emits them to a [Channel]. This decouples the AudioRecord (which has its * own thread) from consumers (which can process at their own pace). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */class DefaultAudioSource(    /** Audio format. Defaults to 16 kHz, 16-bit, mono. */    private val format: AudioFormat = AudioFormat.VOICE_16K,) : AudioSource {    private var audioRecord: AudioRecord? = null    private var captureJob: Job? = null    private var captureScope: CoroutineScope? = null    private var chunkChannel: Channel<AudioChunk>? = null    private var released: Boolean = false    @Volatile    private var session_id: Int = AudioSource.NO_SESSION    override val audioSessionId: Int get() = session_id    override suspend fun start(): Boolean {        if (audioRecord != null) return true // already started        if (released) return false        val minBuf = AudioRecord.getMinBufferSize(            format.sampleRateHz,            AndroidAudioFormat.CHANNEL_IN_MONO,            AndroidAudioFormat.ENCODING_PCM_16BIT,        )        if (minBuf <= 0) return false        // Buffer = max(minBuf, 4 frames) for low-latency but stable capture        val bufferSize = maxOf(minBuf, format.samplesPerFrame * 4)        try {            val record = AudioRecord(                MediaRecorder.AudioSource.VOICE_RECOGNITION,                format.sampleRateHz,                AndroidAudioFormat.CHANNEL_IN_MONO,                AndroidAudioFormat.ENCODING_PCM_16BIT,                bufferSize,            )            if (record.state != AudioRecord.STATE_INITIALIZED) {                record.release()                return false            }            audioRecord = record            session_id = record.audioSessionId            // Start capture coroutine            chunkChannel = Channel(capacity = 32)            captureScope = CoroutineScope(Dispatchers.IO + Job())            captureJob = captureScope?.launch {                val frameSize = format.samplesPerFrame                val buffer = ShortArray(frameSize)                var seq = 0L                val startTime = System.currentTimeMillis()                while (isActive && audioRecord != null) {                    val read = record.read(buffer, 0, frameSize)                    if (read > 0) {                        val chunk = AudioChunk(                            format = format,                            samples = buffer.copyOf(read),                            timestampMs = startTime + (seq * format.frameDurationMs),                            sequenceNumber = seq++,                        )                        chunkChannel?.send(chunk)                    } else if (read == AudioRecord.ERROR_INVALID_OPERATION) {                        break                    }                    // Small delay to prevent busy-looping on errors                    if (read < 0) delay(10)                }            }            record.startRecording()            return true        } catch (e: SecurityException) {            // Permission denied            return false        } catch (e: Throwable) {            return false        }    }    override fun stop() {        captureJob?.cancel()        captureScope?.cancel()        captureJob = null        captureScope = null        chunkChannel?.close()        chunkChannel = null        try {            audioRecord?.stop()        } catch (e: Throwable) { /* ignore */ }        session_id = AudioSource.NO_SESSION    }    override fun chunkStream(): Flow<AudioChunk> {        val channel = chunkChannel ?: throw IllegalStateException("AudioSource not started")        return channel.receiveAsFlow()    }    override fun release() {        if (released) return        released = true        stop()        try {            audioRecord?.release()        } catch (e: Throwable) { /* ignore */ }        audioRecord = null    }}